  /** Object to mirror over. Leave empty and name a bone to always mirror over that bone of the active armature */
  get anim_mirror_object(): H.Ptr<R.Object>;
  set anim_mirror_object(v: R.Object | null);
  /** Bone to use for the mirroring Default: "". */
  get anim_mirror_bone(): H.Ref<string>;
  set anim_mirror_bone(v: H.In<string>);
  /** Object to which matrices are made relative */
  get anim_relative_object(): H.Ptr<R.Object>;
  set anim_relative_object(v: R.Object | null);
  /** Create location keys when fixing to the scene camera Default: False. */
