  set anim_fix_to_cam_use_rot(v: H.In<boolean>);
  /** Create scale keys when fixing to the scene camera Default: False. */
  get anim_fix_to_cam_use_scale(): H.Ref<boolean>;
  set anim_fix_to_cam_use_scale(v: H.In<boolean>);
